    title: "05 沉默是金，寡言是福",
    sourceOriginal: "天地不仁，以萬物為芻狗； 聖人不仁，以百姓為芻狗。 天地之間，其猶橐籥乎？虛而不屈，動而愈出。 多言數窮，不如守中。",
    sourceTranslation: "天地不存在仁與非仁的意識，把萬物當作祭祀時用芻草紮的狗。 聖人效法天地，收斂了自己仁與非仁的意識，把百姓當成這種芻草紮的狗。 天地之間，豈不正像是冶煉時用來鼓風吹火的風箱嗎？中間空虛，越是鼓動，氣流越充沛、用之不竭。 言多必失易招禍端，不如守中。 （如風箱一樣，用時鼓動成風，停時緘默不語）",
    sourceQuote: "多言數窮，不如守中。",
