    sourceTranslation: "得到恩寵和受到屈辱，都會感到心神震驚而不得安寧，重視大的禍患就像重視自己的身體性命一樣。 什麼叫「寵辱若驚」呢？恩寵是上對下給予額外的賜予，所以當受寵者得到額外賜予時，就會感到震驚，如果失去了額外賜予，也會因失寵受辱而感到震驚，從而失去安寧，這就叫做得寵與受辱都感到震驚。 什麼叫「貴大患若身」呢？我們之所以感到大的禍患，是因為我們有身體的存在，如果不顧及到自己的身體，那我們還有什麼禍患呢？ 所以，能做到貴身（珍貴自己生命）那樣去服務於天下的人，才可以把天下大事寄託於他。能做到愛身（愛自己生命）那樣服務於天下的人，才可以把天下的重任交付給他。",
