    sourceTranslation: "有那麼一個「東西」，看它卻看不見它，但它確實存在，只不過超出了人的視力範圍而已，它名叫「夷」（隱）；聽它卻聽不到它，但它確實存在，只不過超出了人的聽力範圍而已，它名叫「希」（暗）；摸它卻摸不著它，但它確實存在，只不過超出了人的感官所能感知而已，它名叫「微」（無）。 倘若有人問我這個看不見、聽不到、摸不著的東西是什麼，我無法直截了當地闡述，只知道它是以上這三方面的渾然一體。 它是一個整體，它又是不明不暗上下無光的。它綿綿不絕卻又無可名狀，還又歸於沒有物質的虛無狀態。 就是說它是無影無形的，是沒有形狀的形狀，沒有物象的物象，這個現象可以體會，但捉摸不到，所以就叫它「 惚 恍」。 迎上去見不到它的源頭，追上去見不到它的蹤跡。 我們只能從它的過去，把握它的現在。必須了解最初的歷史，才能參透「道」的規律。",
