    title: "15 欲成功者的七種行為準則",
    sourceOriginal: "古之善為士者，微妙玄通，深不可識。夫唯不可識，故強為之容： 豫兮，若涉大川； 猶兮，若畏四鄰； 儼兮，其若客； 渙兮，若冰之將釋； 敦兮，其若樸； 曠兮，其若谷； 混兮，其若濁。 孰能濁之以止？靜之徐清； 孰能安之以久？動之徐生。 保此道者，不欲盈。夫唯不盈，故能蔽而新成。",
    sourceTranslation: "古代那善於行道的人，見解微妙而能洞察幽隱，其心靈深不可測。正是因為深不可測，所以只能勉強地給他一個描述和形容： 他小心謹慎，彷彿在冬天裡涉過大河； 他處處警惕，彷彿畏懼四周的鄰居一樣； 他嚴以律己，彷彿在別人家裡做客； 他胸襟瀟灑，彷彿春天裡冰雪融化一樣溫和自如； 他淳厚樸實，彷彿未經雕琢的玉石； 他豁達開闊，彷彿那空山幽谷； 他渾渾沌沌，彷彿是汙水濁流。 誰能在混濁動亂中平靜下來，使身心清靜如水呢？ 誰能在安定祥和中長久守持，使心平氣和徐徐而生呢？ 能遵循此規律的人，能保持謙虛而不盈滿，正因為他不盈滿，所以總能不斷地從陳舊中創新。",
