    title: "20 節操是做人的根本",
    sourceOriginal: "唯之與阿，相去幾何？ 善之與惡，相去何若？ 人之所畏，不可不畏。 荒兮，其未央哉！ 眾人熙熙，如享太牢，如春登台。 我獨泊兮，其未兆，沌沌兮，如嬰兒之未孩，乘乘兮，若無所歸。 眾人皆有餘，而我獨若遺。我愚人之心也哉！ 俗人昭昭，我獨若昏； 俗人察察，我獨悶悶。 忽兮若海，漂兮若無所止。 眾人皆有以，而我獨頑似鄙。 我獨異於人，而貴食母。",
    sourceTranslation: "順從與違逆，相去有多遠？ 美善與醜惡，相去又有多遠？ 令人所懼怕的，我不能不懼怕。 荒唐啊，看不到止境呀！ 眾人都忙著嬉樂，好像在享受大餐，又像春天登高遊覽。 我卻淡然處之，不萌生尋歡作樂的念頭。 混混沌沌啊，就好像嬰兒還不會發出笑聲。 閒閒散散啊，就好像沒有地方可以歸宿。 眾人生活都很富裕，我獨自一人匱乏。 我有一個愚人的心腸啊，混沌無知啊！ 眾人都光耀自炫，而我卻獨自昏昏昧昧。 眾人對利之所在，都非常精明，而我卻一聲不響。 幽遠呀，恬然自得啊，飄飄然好像大海無邊。 眾人都有所作為，而我卻獨自冥頑不化。 我與他們不同，我只注重生命的根本——「道」的境界。",
