    title_id: "n41",
    title: "38 真風流出自真內涵",
    sourceOriginal: "上德不德，是以有德； 下德不失德，是以無德。 上德無為，而無以為； 下德為之，而有以為。 上仁為之，而無以為； 上義為之，而有以為； 上禮為之，而莫之應，則攘臂而扔之。 故失道而後德，失德而後仁，失仁而後義，失義而後禮。 夫禮者，忠信之薄，而亂之首； 前識者道之華，而愚之始。 是以大丈夫處其厚，不居其薄； 處其實，不居其華。故去彼取此。",
    sourceTranslation: "具有上乘品德的人，從來不追求形式上的「德」，這才是真正具備了「德」。 而下乘品德的人，從來不放棄在形式上追求「德」，實際上是沒有真正具備「德」。 真正具備「德」的人，一切順其自然無所作為，而且也是無心作為。 形式上具備「德」的人，喜歡人為地加以施為，而且也是有心作為。 講仁愛的人要做一件事，是沒有私心意圖的，所以容易做好。 講義行的人要做一件事，常有私心目的，所以可以做好的事是有限的。 講禮儀的人去做一件事，是勉強施為，如果沒人響應，於是便揚起手臂使人屈服，這樣的人最終什麼也做不好。 所以，喪失「道」的人才去講「德」；喪失「德」的人才去講「仁」；喪失「仁」的人才去講「義」；喪失「義」的人才去講「禮」。 而所謂的禮儀啊，是人心不夠忠厚，是社會動亂的禍首。 自以為有先見之明，那不過是道的虛華，是愚昧的開始。 所以，大丈夫，選擇淳厚而不選擇輕薄；選擇樸實而不選擇虛華。 因此，便捨棄後者而選擇前者。",
