    title: "39 做人應像頑石一樣厚道而真實",
    sourceOriginal: "昔之得一者，天得一以清，地得一以寧； 神得一以靈，谷得一以盈； 萬物得一以生，侯王得一以為天一正。 其致之，天無以清，將恐裂； 地無以寧，將恐廢； 神無以靈，將恐歇； 谷無以盈，將恐竭； 萬物無以生，將恐滅；侯 王無以 貴 高，將恐蹶。 故貴以賤為本，高必以下為基。 是以侯王自謂孤寡不穀。此非以賤為本耶？非乎！ 故至譽無譽。是故不欲碌碌如玉，落落如石。",
    sourceTranslation: "自古以來，那些保持了自身與「道」相統一的有以下幾種情形： 天得道則清靜明朗，地得道則寧靜安詳； 神得道則靈驗時顯，川谷得道則盈滿； 萬物得道則發展生長，侯王得道則天下太平。 如果不能這樣： 天不清靜，恐怕就要崩裂； 地不安寧，恐怕就會塌陷； 神不靈驗，恐怕就會消失； 川谷不盈滿，恐怕就會乾涸； 萬物不生長，恐怕就會滅絕； 侯王一味尊貴，高高在上，恐怕就會垮台。 所以貴者要以賤者為根本，高者要以下者為基石。 因此，君王自稱孤、寡人、不足，這不正是以賤者為根本嗎？不是嗎？ 所以，追求榮譽反而會沒有榮譽。因此，不要追求像美玉那樣的尊貴華麗，而要像石頭那樣堅潤無光，不在人前張揚。",
