    title: "46 知足者常樂",
    sourceOriginal: "天下有道，卻走馬以糞； 天下無道，戎馬生於郊。 罪莫大於可欲，禍莫大於不知足，咎莫大於欲得。 故知足之足，常足。",
    sourceTranslation: "君王遵循「道」來治理天下，便讓戰馬去耕種糞田； 君王不遵循「道」來治理天下，戰馬只能在戰場上生子。 最大的禍害莫過於不知足，最大的災難莫過於貪得無厭。 所以只有知道滿足而滿足，才會永遠地富足。",
    sourceQuote: "天下有道，卻走馬以糞； 故知足之足，常足。",
