    title_id: "n53",
    title: "50 生死應順其自然",
    sourceOriginal: "出生入死。 生之徒，十有三；死之徒，十有三； 人之生，動之死地，十有三。 夫何故？以其生生之厚。 蓋聞善攝生者，陸行不遇兕虎，入軍不避甲兵。 兕無所投其角，虎無所措其爪，兵無所容其刃。 夫何故？以其無死地。",
    sourceTranslation: "如果人能退出雜欲的羈絆，就能健康地生存；如果人糾纏於無休止的欲念之中，就會因貪欲而致於死地。 生活中，屬於長命的人，占總人數的十分之三；屬於短命的人，也占總人數的十分之三； 而那些本該長命的，但卻要走向死亡的人，同樣是占總人數的十分之三。 這是為什麼呢？因為他們求生的心太切，而產生了眾多雜欲紛爭的緣故。 我曾經聽說善於養生的人，他們走在陸地上，不會怕遇到犀牛老虎，進入打仗的戰陣中，不會被兵器所創傷。 犀牛無法對他施用犄角，老虎無法對他施用利爪，士兵也無法對他施用刀劍。 這又是什麼緣故呢？這是因為他們沒有眾多私心雜欲，沒有進入死亡的領地。",
